'use strict';
window.photoLibrary=(()=>{
const $=id=>document.getElementById(id),safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let config=null,dbPromise=null,renderToken=0,busy=false,removedPhoto=null;
function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open('sq-field-photos',1);request.onupgradeneeded=()=>request.result.createObjectStore('images');request.onsuccess=()=>resolve(request.result);request.onerror=()=>{dbPromise=null;reject(Error('無法開啟本機照片儲存，請允許網站儲存資料'))}});return dbPromise}
async function get(id){const database=await db();return new Promise((resolve,reject)=>{const request=database.transaction('images').objectStore('images').get(id);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(Error('無法讀取照片'))})}
async function putMany(items){const database=await db();return new Promise((resolve,reject)=>{const transaction=database.transaction('images','readwrite');for(const item of items)transaction.objectStore('images').put(item.dataUrl,item.id);transaction.oncomplete=resolve;transaction.onerror=()=>reject(Error('照片儲存失敗，可能是空間不足'));transaction.onabort=()=>reject(Error('照片儲存未完成'))})}
const validUrl=url=>typeof url==='string'&&url.length<=480000&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(url);
function linkName(photo,data){if(!photo.segmentId)return '全場／未指定路段';const index=data.segments.findIndex(s=>s.id===photo.segmentId);return index<0?'原路段已刪除，請重新指定':'第 '+(index+1)+' 段'+(data.segments[index].type==='gate'?'大門':'圍籬')}
async function render(){if(!config)return;const data=config.getData(),token=++renderToken;const photos=data.photos||[];$('photoCount').textContent=photos.length+' / 20 張';$('undoPhoto').disabled=!removedPhoto||removedPhoto.owner!==data;$('photoList').innerHTML=photos.length?photos.map((p,i)=>`<article class="photoCard" data-photo-id="${safe(p.id)}"><button type="button" class="photoZoom" data-photo-open="${safe(p.id)}" aria-label="放大照片 ${i+1} ${safe(p.name)}"><img alt="勘場照片 ${i+1} ${safe(p.name)}"><span>點照片放大</span></button><p class="photoName">${safe(p.name)}</p><label>對應路段<select data-photo-field="segmentId"><option value="">全場／未指定</option>${data.segments.map((s,j)=>`<option value="${safe(s.id)}" ${p.segmentId===s.id?'selected':''}>第 ${j+1} 段${s.type==='gate'?'大門':'圍籬'}</option>`).join('')}${p.segmentId&&!data.segments.some(s=>s.id===p.segmentId)?`<option value="${safe(p.segmentId)}" selected>原路段已刪除，請重新指定</option>`:''}</select></label><label>照片備註<textarea data-photo-field="caption" rows="2" maxlength="500" placeholder="例如：這個轉角有排水溝、怪手進場位置">${safe(p.caption)}</textarea></label><p class="photoPrint">${safe(linkName(p,data))}：${safe(p.caption)}</p><button type="button" data-photo-remove="${safe(p.id)}">移除照片 ${i+1}</button></article>`).join(''):'<p class="muted">尚未加入照片。可拍攝現場入口、轉角、地面、障礙物與大門位置。</p>';
await Promise.all(photos.map(async p=>{try{const url=await get(p.id);if(token!==renderToken)return;const card=Array.from($('photoList').children).find(el=>el.dataset.photoId===p.id);if(card){if(validUrl(url))card.querySelector('img').src=url;else{card.querySelector('img').alt='照片檔遺失，請重新加入';card.querySelector('.photoName').textContent=p.name+'（缺少照片檔）'}}}catch(error){if(token===renderToken)$('photoCount').textContent='照片讀取失敗，請匯出備份或重新加入'}}))}
async function compress(file){if(file.size>20*1024*1024)throw Error(file.name+' 超過20MB，請先縮小');if(!file.type.startsWith('image/'))throw Error('請選擇圖片檔');const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error(file.name+' 無法讀取，請改用 JPEG、PNG 或 WebP'));image.src=url});if(!img.naturalWidth||img.naturalWidth*img.naturalHeight>50000000)throw Error('圖片尺寸過大');let scale=Math.min(1,1600/Math.max(img.naturalWidth,img.naturalHeight)),encoded='',width,height;for(let attempt=0;attempt<5;attempt++){width=Math.max(1,Math.round(img.naturalWidth*scale));height=Math.max(1,Math.round(img.naturalHeight*scale));const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const context=canvas.getContext('2d');context.fillStyle='white';context.fillRect(0,0,width,height);context.drawImage(img,0,0,width,height);encoded=canvas.toDataURL('image/jpeg',.78);canvas.width=canvas.height=1;if(encoded.length<=460000)break;scale*=.75}if(!validUrl(encoded))throw Error('圖片縮圖失敗，請先縮小後再加入');return{width,height,dataUrl:encoded}}finally{URL.revokeObjectURL(url)}}
async function add(files){if(busy)return;const owner=config.getData();if(!files.length)return;if(owner.photos.length+files.length>20){config.notice('每案最多20張，請分批選擇或先移除照片');return}busy=true;$('photoMessage').textContent='正在處理照片，請稍候…';try{const items=[];for(const file of files){const image=await compress(file);items.push({id:crypto.randomUUID(),name:file.name.slice(0,180)||'勘場照片.jpg',caption:'',segmentId:'',addedAt:new Date().toISOString(),...image})}if(owner!==config.getData())throw Error('案件已切換，這批照片尚未加入，請在目前案件重新選擇');await putMany(items);if(owner!==config.getData())throw Error('案件已切換，請重新選擇照片');owner.photos.push(...items.map(({dataUrl,...p})=>p));config.changed();await render();config.notice('已加入 '+items.length+' 張照片；請匯出完整資料備份')}catch(error){config.notice(error.message)}finally{busy=false;$('photoMessage').textContent='';$('photoFiles').value='';$('photoCamera').value=''}}
async function expand(photos){return Promise.all(photos.map(async p=>{const dataUrl=await get(p.id);if(!validUrl(dataUrl))throw Error('照片「'+p.name+'」缺少本機影像，請重新加入後再匯出');return{...p,dataUrl}}))}
async function importPhotos(photos){const items=[];for(const p of photos){if(!validUrl(p.dataUrl))throw Error('備份照片內容不正確或缺少照片');const dimensions=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve({width:image.naturalWidth,height:image.naturalHeight});image.onerror=()=>reject(Error('備份照片無法解碼'));image.src=p.dataUrl});if(!dimensions.width||dimensions.width*dimensions.height>50000000)throw Error('備份照片尺寸不正確');items.push({...p,...dimensions,id:crypto.randomUUID()})}if(items.length)await putMany(items);return items.map(({dataUrl,...p})=>p)}
function start(options){config=options;$('addPhotos').onclick=()=>$('photoFiles').click();$('takePhoto').onclick=()=>$('photoCamera').click();$('photoFiles').onchange=e=>add(Array.from(e.target.files));$('photoCamera').onchange=e=>add(Array.from(e.target.files));$('photoList').addEventListener('change',e=>{const key=e.target.dataset.photoField;if(!key)return;e.stopPropagation();const data=config.getData(),photo=data.photos.find(p=>p.id===e.target.closest('[data-photo-id]').dataset.photoId);if(!photo)return;photo[key]=e.target.value;const text=e.target.closest('.photoCard').querySelector('.photoPrint');text.textContent=linkName(photo,data)+'：'+photo.caption;config.changed()});$('photoList').addEventListener('click',async e=>{const data=config.getData(),open=e.target.closest('[data-photo-open]'),remove=e.target.closest('[data-photo-remove]');if(remove){const index=data.photos.findIndex(p=>p.id===remove.dataset.photoRemove);if(index<0)return;removedPhoto={owner:data,index,photo:data.photos[index]};data.photos.splice(index,1);config.changed();await render();config.notice('已移除，可按「復原移除照片」加回');return}if(open){try{const photo=data.photos.find(p=>p.id===open.dataset.photoOpen);if(!photo)return;const image=await get(photo.id);if(!validUrl(image))throw Error('照片檔遺失，請重新加入');$('photoLarge').src=image;$('photoLarge').alt=photo.name;$('photoDialogTitle').textContent=photo.name;$('photoLargeNote').textContent=linkName(photo,data)+(photo.caption?'：'+photo.caption:'');$('photoDialog').showModal()}catch(error){config.notice(error.message)}}});$('undoPhoto').onclick=()=>{const data=config.getData();if(!removedPhoto||removedPhoto.owner!==data)return;if(data.photos.length>=20)return config.notice('每案最多20張');data.photos.splice(Math.min(removedPhoto.index,data.photos.length),0,removedPhoto.photo);removedPhoto=null;config.changed();render()};$('closePhoto').onclick=()=>$('photoDialog').close();render()}
return{start,render,expand,importPhotos};
})();

