(function(root){
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bases={direct:'單獨埋入',buried:'埋入／混凝土',plate:'底板固定'},mats={galv:'鍍鋅',highgalv:'高鍍鋅',pvc:'PVC包覆（綠）'};
